export N8N_API_KEY=$(grep N8N_API_KEY .env | cut -d '=' -f2)
export N8N_API_URL=$(grep N8N_API_URL .env | cut -d '=' -f2)
curl -s -X GET "${N8N_API_URL}workflows" -H "X-N8N-API-KEY: ${N8N_API_KEY}"

